      dst += 4;
      src += 4;
    }

    while (i) {
      storea(dst, loada<Vec2xF64>(src) + m21_m20);

      i--;
      dst++;
      src++;
    }
  }
  else {
    while (i >= 4) {
      Vec2xF64 v0 = loadu<Vec2xF64>(src + 0) + m21_m20;
