  }

  EXPECT_EQ(image_row(dst_data, 2)[4], 0u);
  EXPECT_EQ(image_row(dst_data, 6)[4], 0u);
}

static void test_simd_box_blur() noexcept {
  INFO("Testing SIMD box blur parity");

  constexpr int kW = 37;
  constexpr int kH = 29;

