  EXPECT_SUCCESS(inner.get_data(&inner_data));

  uint32_t edge_pixel = image_pixel(inner_data, 4, 4);
  EXPECT_EQ((edge_pixel >> 24) & 0xFFu, 255u);
  EXPECT_TRUE(((edge_pixel >> 16) & 0xFFu) >= 126u && ((edge_pixel >> 16) & 0xFFu) <= 128u);

