  for (uint32_t i = 0; i < repeat; i++)
    consume(BLImageFilter::gaussian_blur_approx(dst, src, blur_options));
  timer.stop();
  print_result("gaussian (3x box)", timer, repeat, width, height);
  double approx_ms = timer.duration();

